use xiom.io;

use xiom.string;
fn fetch_score(player: Str) -> Result[Int, Str] {
  if player == "Alice" { return Ok(1200); }
  if player == "Bob"   { return Ok(800); }
  return Err("Player not found");
}

fn main() -> Int {
  let s1 = fetch_score("Alice").unwrap_or(0);
  let s2 = fetch_score("Charlie").unwrap_or(0);
  let s3 = fetch_score("Bob").unwrap_or(0);
  io.println(string.int_to_str(s1));
  io.println(string.int_to_str(s2));
  io.println(string.int_to_str(s3));
  return 0;
}
